  /* j6-jukugo */ (function (a) { for (var k in a) E[k] = a[k]; })({"「乗車」の 組み立ては？": "「車に 乗る」と 下から 読める。動作（乗）＋ その 相手（車）の 形。読み下して 確かめる のが コツ。", "「強弱」と 同じ 組み立ての 熟語は？": "「強い⇔弱い」は 反対の 意味の 組み合わせ。「高い⇔低い」も 同じ。", "「入学」の 組み立ては？": "「学校に 入る」と 下から 読める。動作＋目的の 形。", "四字熟語「春夏秋冬」の 組み立ては？": "春・夏・秋・冬が 一字ずつ 対等に ならんでいる。どれが 上・下と いう 関係は ない。", "「無理」の「無」の はたらきは？": "「無」は 下の「理」を 打ち消し「理が 無い」と いう 意味に する。", "「不足」の 組み立ては？": "「不」が「足りる」を 打ち消して「足りない」。打ち消しの 字は 不・無・非・未。", "「未定」の 組み立ては？": "「未」は「まだ〜ない」。「未定」＝まだ 決まって いない。", "三字熟語「図書館」の 組み立ては？": "「図書（本）」＋「館（建物）」＝本の 建物。2字の 熟語に 1字が ついた 形。", "「骨折」の 組み立ては？": "「骨が 折れる」と 上から 読める。上が 主語（何が）、下が 述語（どうする）。", "「開会」の 組み立ては？": "「会を 開く」と 下から 読める。動作＋目的。", "「公私」の 組み立ては？": "「公（おおやけ）⇔私（わたくし）」は 対の 意味。", "「校庭」の 組み立ては？": "「学校の 庭」。上の「校」が 下の「庭」を くわしく している。", "「人造」の 組み立ては？": "「人が 造る」と 上から 読める。主語＋述語。", "「加熱」の 組み立ては？": "「熱を 加える」と 下から 読める。", "三字熟語「不公平」の 組み立ては？": "「不」＋「公平」で「公平で ない」。打ち消しの 1字＋2字の 熟語。", "「読書」は「書を 読む」。このような 熟語と 同じ 組み立ては？": "「山に 登る」も 下から 読む 形。読書（書を 読む）と 同じ 組み立て。", "「高低」の 組み立ては？": "「高い⇔低い」は 反対の 意味。", "「雷鳴」の 組み立ては？": "「雷が 鳴る」。主語＋述語。", "「地震」の 組み立ては？": "「地が 震える」。主語＋述語。", "「無料」の 組み立ては？": "「料（料金）が 無い」。打ち消しの「無」。", "「未来」の 組み立ては？": "「未来」＝まだ 来ていない 時。「未」が 打ち消し。", "「登山」の 組み立ては？": "「山に 登る」。動作＋目的。", "三字熟語「松竹梅」の 組み立ては？": "松・竹・梅が 一字ずつ 対等に ならぶ。おめでたい ものを 3つ ならべた。", "「森林」の 組み立ては？": "「森」も「林」も 木が 多い 所。にた 意味の 組み合わせ。", "「河川」の 組み立ては？": "「河」も「川」も かわ。にた 意味。", "「苦楽」の 組み立ては？": "「苦しい⇔楽しい」は 反対の 意味。", "四字熟語「自然保護」の 組み立ては？": "「自然を 保護する」と 読める。前半が 目的、後半が 動作。", "「強弱」の 組み立ては？": "「強い⇔弱い」は 反対の 意味。", "「読書」の 組み立ては？": "「書を 読む」と 下から 読める。", "「青空」の 組み立ては？": "「青い 空」。上が 下を くわしく する。", "「晴天」の 組み立ては？": "「晴れた 天（空）」。上が 下を くわしく する。", "「頭痛」の 組み立ては？": "「頭が 痛む」。主語＋述語。", "「握手」の 組み立ては？": "「手を 握る」。動作＋目的。", "「再会」の 組み立ては？": "「再び 会う」。上の「再」が どのように 会うかを くわしく している。", "「白紙」の 組み立ては？": "「白い 紙」。上が 下を くわしく する。", "「岩石」の 組み立ては？": "「岩」も「石」も いし。にた 意味。", "「不便」の 組み立ては？": "「便（便利）で ない」。打ち消しの「不」。", "「日没」の 組み立ては？": "「日が 没する（しずむ）」。主語＋述語。", "「年長」の 組み立ては？": "「年が 長じる（上）」。主語＋述語。", "「急増」の 組み立ては？": "「急に 増える」。上が どのように 増えるかを くわしく する。", "「熱湯」の 組み立ては？": "「熱い 湯」。上が 下を くわしく する。", "「勝敗」の 組み立ては？": "「勝つ⇔敗れる」は 反対の 意味。", "「国旗」の 組み立ては？": "「国の 旗」。上が 下を くわしく する。", "「損得」の 組み立ては？": "「損⇔得」は 反対の 意味。", "「縦横」の 組み立ては？": "「縦⇔横」は 対の 意味。", "「深海」の 組み立ては？": "「深い 海」。上が 下を くわしく する。", "「前後」の 組み立ては？": "「前⇔後」は 反対の 意味。", "「無理」の 組み立ては？": "「理が 無い」。打ち消しの「無」。", "「県立」の 組み立ては？": "「県が 立てる（つくる）」。主語＋述語。", "「不安」の 組み立ては？": "「安らかで ない」。打ち消しの「不」。", "「授受」の 組み立ては？": "「授ける（あたえる）⇔受ける」は 対の 意味。", "「非常」の 組み立ては？": "「常（ふつう）で ない」。打ち消しの「非」。", "「激流」の 組み立ては？": "「激しい 流れ」。上が 下を くわしく する。", "「絵画」の 組み立ては？": "「絵」も「画」も え。にた 意味。", "「日没」は「日が 没する」。同じ 組み立ての 熟語は？": "「地が 震える」も 主語＋述語。日没（日が 没する）と 同じ 組み立て。", "「就職」の 組み立ては？": "「職に 就く」。下から 読める。", "「帰国」の 組み立ては？": "「国に 帰る」。下から 読める。", "「洋服」の 組み立ては？": "「西洋の 服」。上が 下を くわしく する。", "三字熟語「新記録」の 組み立ては？": "「新しい」＋「記録」。1字が 2字の 熟語を くわしく する。", "「寒冷」の 組み立ては？": "「寒い」も「冷たい」も にた 意味。", "「国営」の 組み立ては？": "「国が 営む」。主語＋述語。", "「単独」の 組み立ては？": "「単（ひとつ）」も「独（ひとり）」も にた 意味。", "「消火」の 組み立ては？": "「火を 消す」。下から 読める。", "「作文」の 組み立ては？": "「文を 作る」。下から 読める。", "「曲線」の 組み立ては？": "「曲がった 線」。上が 下を くわしく する。", "「植樹」の 組み立ては？": "「樹（木）を 植える」。下から 読める。", "「増加」の 組み立ては？": "「増える」も「加わる」も にた 意味。", "「学習」の 組み立ては？": "「学ぶ」も「習う」も にた 意味。", "「無限」の 組み立ては？": "「限りが 無い」。打ち消しの「無」。", "「豊富」の 組み立ては？": "「豊か」も「富む」も にた 意味。", "「身体」の 組み立ては？": "「身」も「体」も からだ。にた 意味。", "「明暗」の 組み立ては？": "「明るい⇔暗い」は 反対の 意味。", "「救助」の 組み立ては？": "「救う」も「助ける」も にた 意味。", "「着席」の 組み立ては？": "「席に 着く」。下から 読める。", "「開閉」の 組み立ては？": "「開く⇔閉じる」は 反対の 意味。", "「永久」の 組み立ては？": "「永い」も「久しい」も 長く 続く 意味。にた 意味。", "「善悪」の 組み立ては？": "「善い⇔悪い」は 反対の 意味。", "「道路」の 組み立ては？": "「道」も「路」も みち。にた 意味。", "「予告」の 組み立ては？": "「予め（前もって）告げる」。上が どのように 告げるかを くわしく する。", "「投票」の 組み立ては？": "「票を 投じる」。下から 読める。", "「往復」の 組み立ては？": "「往く（行く）⇔復る（帰る）」は 反対の 意味。", "「温暖」の 組み立ては？": "「温かい」も「暖かい」も にた 意味。", "「売買」の 組み立ては？": "「売る⇔買う」は 反対の 意味。", "「尊敬」の 組み立ては？": "「尊ぶ」も「敬う」も にた 意味。"});
  /* j6-bunpo */ (function (a) { for (var k in a) E[k] = a[k]; })({"「走る」の品詞は？": "「走る」は 動きを 表し、言い切りが ウ段（る）で 終わる 動詞。", "「犬が走る」の述語は？": "述語は「どうする・どんなだ・何だ」に あたる 言葉。「犬が」どう する？→「走る」。", "「食べない」の「ない」の品詞は？": "「ない」は 動詞に ついて 打ち消しの 意味を そえる 助動詞。1人では 使えない。", "「急ぐ」の反対語は？": "「急ぐ」は 速く する こと、反対は「ゆっくり（する）」。意味の 反対を 考えよう。", "「目が回る」のような体の一部を使った言い回しを何という？": "体の 一部を 使い、2語 以上で 特別な 意味に なる 言い回しが 慣用句。「目が 回る」＝とても いそがしい。", "「だから」の品詞は？": "「だから」は 前と 後ろの 文を つなぐ 接続詞（理由→結果）。", "「始まる」の反対語は？": "「始まる」⇔「終わる」。", "「とても」の品詞は？": "「とても」は 様子や 程度を くわしく する 副詞。活用しない。", "「きれいだ」の品詞は？": "「きれいだ」は 様子を 表し「〜だ」で 終わる 形容動詞。「きれいな 花」と 形を 変える。", "「公園で遊ぶ」の「で」の役割は？": "「で」は「公園で」と 場所を 表す 助詞。", "「ああ」「おお」などの品詞は？": "「ああ」「おお」は 感動や よびかけを 表す 感動詞。", "「犬が走る」の主語は？": "主語は「何が・だれが」に あたる 言葉。「犬が」。", "「僕は本を読みます」の「を」の役割は？": "「を」は 動作の 対象（何を）を 表す 助詞。「本を 読む」。", "「私は毎日牛乳を飲む」の「毎日」の役割は？": "「毎日」は いつ 飲むかを くわしく する 修飾語。述語「飲む」に かかる。", "「明るい」の反対語は？": "「明るい」⇔「暗い」。", "「れる」「られる」などの品詞は？": "「れる・られる」は 受け身・可能などの 意味を そえる 助動詞。", "「彼は速く走った」の「速く」は何を修飾している？": "「速く」は どのように「走った」かを くわしく する。修飾語は かかる 言葉を さがそう。", "次の文の述語はどれ？「空がとても青い」": "「空が どんなだ？」→「青い」。「とても」は「青い」を くわしく する 修飾語。", "「美しい」の品詞は？": "「美しい」は 様子を 表し「い」で 終わる 形容詞。", "音読みの特徴として正しいのは？": "音読みは 中国から 伝わった 読み方。音だけでは 意味が わかりにくい（サン）。", "意味が反対の言葉を何という？": "意味が 反対の 言葉は 対義語（反対語）。", "漢字4文字で意味をもつ熟語を何という？": "漢字 4字で 1つの 意味を 表す 熟語が 四字熟語。", "「しかし」の品詞は？": "「しかし」は 前と 逆の ことを つなぐ 接続詞。", "「多い」の反対語は？": "「多い」⇔「少ない」。", "意味が似ている言葉を何という？": "意味が にている 言葉は 類義語。", "「花」の品詞は？": "「花」は ものの 名前を 表す 名詞。", "「が」「を」「に」などの品詞は？": "「が・を・に」は 言葉の あとに ついて 関係を しめす 助詞。", "「静かだ」の品詞は？": "「静かだ」は「〜だ」で 終わる 形容動詞。", "「ゆっくり歩く」の「ゆっくり」の品詞は？": "「ゆっくり」は どのように 歩くかを くわしく する 副詞。", "「山」の音読みはどれ？": "「山」の 音読みは サン（富士山）。訓読みは やま。", "訓読みの特徴として正しいのは？": "訓読みは 漢字に 日本語の 意味を あてた 読み方。聞いて 意味が わかる（やま）。", "「入る」の反対語は？": "「入る」⇔「出る」。", "「花子が太郎にプレゼントをあげた」の「花子が」は？": "「花子が」は だれが あげたかを 表す 主語。", "「大きな犬がほえた」の主語は？": "「大きな」は「犬」を くわしく する 修飾語。主語は「犬が」。", "「山」の訓読みはどれ？": "「山」の 訓読みは やま。", "同じ読みで意味が違う言葉を何という？": "同じ 読みで 意味が ちがう 言葉は 同音異義語（例：かいとう＝回答・解答）。", "文の終わりを「〜だ」「〜である」で結ぶ文体を何という？": "「〜だ・〜である」で 終わる 文体は 常体。作文や 新聞で 使う。", "「学校へ行く」の「へ」の役割は？": "「へ」は 方向を 表す 助詞（学校へ 向かって）。", "「明日は晴れるだろう」の「だろう」の品詞は？": "「だろう」は おしはかる（推量）意味を そえる 助動詞。", "「書く」の活用形で「書きます」の「書き」は何形？": "「ます」に 続く 形は 連用形（書き）。", "「楽しい」の反対語は？": "「楽しい」⇔「悲しい」。", "「もし」の品詞は？": "「もし」は「〜なら」と 呼応する 副詞。後ろの 言い方を 決める。", "「犬も歩けば棒に当たる」のような言い回しを何という？": "昔からの 教えや 知恵を 短く 表した 言葉が ことわざ。", "「雨が降ったので、傘をさした」の「ので」の役割は？": "「ので」は 前の 文が 理由で ある ことを しめす 接続助詞。", "文の終わりを「〜です」「〜ます」で結ぶ文体を何という？": "「〜です・〜ます」で 終わる 文体は 敬体。ていねいな 感じに なる。", "「深い」の反対語は？": "「深い」⇔「浅い」。", "「書く」の活用形で「書かない」の「書か」は何形？": "「ない」に 続く 形は 未然形（書か）。", "「太い花が咲いた」で間違っている言葉は？": "花には ふつう「太い」は 使わない（「大きな」「きれいな」などが 合う）。言葉と 言葉の 組み合わせが 合っているか 考えよう。", "「お・ご」をつけて丁寧にする言葉づかいを何という？": "「お花」「ご飯」など、お・ごを つけて 言葉を 上品に するのが 美化語。", "「赤い花が咲く」の修飾語は？": "「赤い」は「花」を くわしく する 修飾語。"});
  /* j6-classic */ (function (a) { for (var k in a) E[k] = a[k]; })({"古語「いと」の意味は？": "「いと」は とても・たいへん。「いと うつくし」＝とても かわいい。", "古語「いみじ」の意味は？": "「いみじ」は 程度が はなはだしい。良い 意味にも 悪い 意味にも 使う。", "「徒然草」の冒頭は？": "「つれづれなるままに」＝することが なく 退屈なので。兼好法師の 徒然草の はじまり。", "「七夕」はどの季節の季語？": "七夕は 昔の こよみ（旧暦）で 7月＝秋。季語は 昔の こよみで 考える。", "「万葉集」はどんな本？": "万葉集は 奈良時代の 日本最古の 和歌集。天皇から 農民まで いろいろな 人の 歌。", "「古事記」はどんな本？": "古事記（712年）は 神話や 天皇の 歴史を 書いた 日本最古の 歴史書。", "「秋の季語」はどれ？": "紅葉（もみじ）は 秋の 季語。木の 葉が 色づく 季節。", "「ちはやぶる」は何にかかる枕詞？": "「ちはやぶる」は「神」に かかる 枕詞。意味より 調子を ととのえる はたらき。", "「奥の細道」の作者は？": "奥の細道は 江戸時代の 松尾芭蕉の 紀行文（旅の 記録）。", "「枕草子」の冒頭は？": "「春は あけぼの」＝春は 明け方が いい。清少納言の 季節の 感じ方。", "「方丈記」の作者は？": "方丈記は 鎌倉時代の 鴨長明。世の中の 無常を 書いた 随筆。", "古語「おどろく」の意味は？": "古語「おどろく」は 目を 覚ます・はっと 気づく。今の「びっくり」とは 少し ちがう。", "古語「めでたし」の意味は？": "古語「めでたし」は すばらしい・立派だ。今の「めでたい」より 意味が 広い。", "「たらちねの」は何にかかる枕詞？": "「たらちねの」は「母」に かかる 枕詞。", "古語「をかし」の意味は？": "古語「をかし」は 趣が ある・おもしろい。枕草子に 多く 出てくる。", "「夏の季語」はどれ？": "蛍は 夏の 季語。夏の 夜に 光る。", "「平家物語」は何について書かれている？": "平家物語は 平家（平氏）が さかえ、ほろびる までを えがいた 物語。「諸行無常」の 考え。", "「おくのほそ道」はどの時代に書かれた？": "奥の細道は 江戸時代（元禄の ころ）。", "古語「つきづきし」の意味は？": "「つきづきし」は 似つかわしい・ふさわしい。枕草子「冬は つとめて」に 出てくる。", "「花火」はどの季節の季語？": "花火は 夏の 季語。", "「百人一首」とはどんなもの？": "百人一首は 百人の 歌人の 和歌を 一首ずつ 集めた もの。かるたでも 遊ぶ。", "「方丈記」の冒頭は？": "「ゆく河の 流れは 絶えずして」。川の 水が 変わり続ける ように 世の中も 変わる と 書いた。", "「枕草子」の作者は？": "枕草子は 清少納言。", "和歌で使われる「枕詞」とは？": "枕詞は 決まった 言葉の 前に 置き、調子を ととのえる 言葉（例：あしびきの→山）。", "「冬の季語」はどれ？": "雪は 冬の 季語。", "「古池や蛙飛びこむ水の音」の作者は？": "「古池や」の 句は 松尾芭蕉。静けさを 小さな 音で 表した。", "日本最古の物語と言われるのは？": "竹取物語は 日本最古の 物語と いわれる。かぐや姫の 話。", "古語「やがて」の意味は？": "古語「やがて」は すぐに・そのまま。今の「そのうち」とは ちがう ので 注意。", "随筆（エッセイ）にあたる古典はどれ？": "枕草子は 見たこと・感じたことを 自由に 書いた 随筆。", "俳句は何音でできている？": "俳句は 五・七・五の 十七音。", "「やせ蛙まけるな一茶これにあり」の作者は？": "小林一茶は 小さな 生き物に やさしい 句を 多く よんだ。「やせ蛙」を 応援している。", "短歌は何音でできている？": "短歌は 五・七・五・七・七の 三十一音。俳句より 七・七 長い。", "「奥の細道」の冒頭は？": "「月日は 百代の 過客にして」＝月日は 永遠の 旅人。芭蕉の 奥の細道の はじまり。", "「菜の花や月は東に日は西に」の作者は？": "与謝蕪村は 絵の ような 句を よんだ。菜の花畑に 東の 月と 西の 夕日。", "「こいのぼり」はどの季節の季語？": "こいのぼりは 5月の 端午の節句で、俳句では 夏（初夏）の 季語。", "「柿食えば鐘が鳴るなり法隆寺」の作者は？": "正岡子規の 句。明治時代に 俳句を 新しく した 人。", "「春の季語」はどれ？": "桜は 春の 季語。", "俳句に必要なものは？": "俳句には 季節を 表す 季語を 入れる。", "「竹取物語」の主人公は？": "竹取物語の 主人公は かぐや姫。", "「あしびきの」は何にかかる枕詞？": "「あしびきの」は「山」に かかる 枕詞。", "古語「あはれ」の意味は？": "古語「あはれ」は しみじみとした 感動。うれしい ときも 悲しい ときも 使う。", "「源氏物語」の作者は？": "源氏物語は 紫式部。", "「万葉集」はどの時代に編まれた？": "万葉集は 奈良時代。", "「日本書紀」はどんな本？": "日本書紀（720年）は 国が まとめた 正式な 歴史書。漢文で 書かれた。", "「平家物語」の冒頭は？": "「祇園精舎の 鐘の声 諸行無常の 響きあり」。平家物語の はじまり。", "「竹取物語」でかぐや姫を見つけたのは？": "竹取の翁（おきな）が 光る 竹の 中から かぐや姫を 見つけた。", "「源氏物語」はどの時代に書かれた？": "源氏物語は 平安時代。", "古語「あさまし」の意味は？": "古語「あさまし」は おどろき あきれる。今の「あさましい（いやしい）」と ちがう。", "「源氏物語」の主人公は？": "源氏物語の 主人公は 光源氏。", "「徒然草」の作者は？": "徒然草は 鎌倉時代の 兼好法師（吉田兼好）。"});
  /* j6-kun */ (function (a) { for (var k in a) E[k] = a[k]; })({"「すがたを（あらわす）」（見えるように なる）の 漢字は？": "「現す」は かくれていた ものが 見える ように なる こと。「表す」（気持ちを 外に 出す）、「著す」（本を 書く）と 使い分ける。", "「重さを（はかる）」の 漢字は？": "重さ・量は「量る」。長さ・深さは「測る」、時間・数は「計る」。何を はかるかで 漢字を 決める。", "「病気が（なおる）」の 漢字は？": "病気や けがが よく なるのは「治る」。物が もとに もどるのは「直る」。", "「小学生を（たいしょう）に した 本」の 漢字は？": "「対象」は 相手・目標と なる もの。「対照」（くらべる）、「対称」（つり合う 形）と 区別しよう。", "「時間を（はかる）」の 漢字は？": "時間や 数を はかるのは「計る」（時計の 計）。", "形声文字（意味を 表す 部分＋音を 表す 部分）は どれ？": "「晴」は 日（意味：天気）＋青（音：セイ）。意味と 音の 部分の 組み合わせが 形声文字。", "「こわれた いすが（なおる）」の 漢字は？": "こわれた 物が もとに もどるのは「直る」。人の 病気なら「治る」。", "「国を（おさめる）」の 漢字は？": "国や 世の中を しずめ まとめるのは「治める」（政治の 治）。", "「銅」の 中で 意味を 表す 部分は？": "「銅」は 金（意味：金属）＋同（音：ドウ）。金へんは 金属に 関係する。", "「（いがい）な 結果」の 漢字は？": "「意外」は 思いの ほか。「以外」（それを のぞく ほか）と 区別しよう。", "「部屋が（あたたかい）」の 漢字は？": "気温や 部屋の 空気は「暖かい」。さわって わかる 物の 温度は「温かい」。", "三字熟語「松竹梅」の 組み立ては？": "松・竹・梅が 3つ 対等に ならぶ 組み立て。", "「（あたたかい）スープ」の 漢字は？": "スープなど 物の 温度は「温かい」。気温は「暖かい」。", "「ぼく（いがい）は みんな 来た」の 漢字は？": "「以外」は それを のぞいた ほか。「ぼく 以外」＝ぼくを のぞく。", "「学問を（おさめる）」の 漢字は？": "学問や 技を 身に つけるのは「修める」（修業の 修）。", "「花」の 中で 音を 表す 部分は？": "「花」は 艹（意味：草）＋化（音：カ）。", "「清・晴・精・静」に 共通する 音を 表す 部分は？": "「清・晴・精・静」は どれも「青」が 音（セイ）を 表す。形声文字の なかま。", "「（あつい）本」の 漢字は？": "ものの 厚みは「厚い」。気温は「暑い」、物の 温度は「熱い」。", "「成功を（おさめる）」の 漢字は？": "成功や 成果を 手に 入れるのは「収める」（収穫の 収）。", "「気持ちを 顔に（あらわす）」の 漢字は？": "気持ちや 考えを 外に 出すのは「表す」（表現の 表）。", "「（たいしょう）的な 性格」（ちがいが はっきり）の 漢字は？": "ちがいが はっきりするのは「対照」（対照的）。くらべて 照らし合わせる。", "「今日は とても（あつい）」（気温）の 漢字は？": "気温が 高いのは「暑い」（暑中見舞いの 暑）。", "「長さを（はかる）」の 漢字は？": "長さ・深さ・広さは「測る」（測量の 測）。", "「税金を（おさめる）」の 漢字は？": "お金や 品物を わたすのは「納める」（納税の 納）。", "「本を（あらわす）」（書いて 出す）の 漢字は？": "本を 書いて 出すのは「著す」（著者の 著）。", "「左右（たいしょう）の 図形」の 漢字は？": "左右が つり合った 形は「対称」（線対称）。算数でも 使う。", "「（あつい）お茶」の 漢字は？": "物の 温度が 高いのは「熱い」（熱湯の 熱）。", "「無関心」の「無」の はたらきは？": "「無」は 下の「関心」を 打ち消して「関心が ない」。", "三字熟語「新記録」の 組み立ては？": "「新」が「記録」を くわしく する。1字＋2字の 熟語。"});
  /* j6-bun */ (function (a) { for (var k in a) E[k] = a[k]; })({"主語と 述語が 正しく 対応している 文は？": "主語「夢は」に 合う 述語は「〜ことです」。主語と 述語を つなげて 読むと 正しいか わかる。", "まちがった 敬語は どれ？": "「まいる」は 自分が へりくだる 謙譲語。先生（目上）の 動作には 尊敬語「いらっしゃる」を 使う。", "「この 本の よい ところは、絵が きれいです。」の 直し方は？": "「よい ところは」→「〜ところです」。主語と 述語を そろえて ねじれを 直す。", "「先生が 話を する。」の 主語は？": "主語は「だれが」に あたる「先生が」。", "「わたしが 心配なのは、雨が ふる。」を 正しく 直すと？": "「心配なのは」→「〜ことだ」で 受ける。主語と 述語の 対応。", "「わたしが 作品を 見る。」を 謙譲語に すると？": "「見る」の 謙譲語は「拝見する」。尊敬語なら「ご覧に なる」。", "「わたしが ケーキを 食べる。」を 謙譲語に すると？": "「食べる」の 謙譲語は「いただく」。尊敬語なら「めしあがる」。", "相手を 高めて 言う 敬語は？": "相手の 動作を 高めて 言うのが 尊敬語（いらっしゃる・おっしゃる）。", "「ぼくは 本を 読みながら、弟は テレビを 見た。」の 直し方として よいのは？": "「〜ながら」は 同じ 人が 2つの ことを する とき。2人の 動作は「〜し、〜」で つなぐ。", "その 地方だけで 使われる ことばを 何と いう？": "その 地方だけで 使う ことばが 方言。地域の 文化を 表す 大切な ことば。", "自分を 低めて 相手を 高める 敬語は？": "自分の 動作を 低めて 相手を 高めるのが 謙譲語（うかがう・申す）。", "「校長先生が 言う。」を 尊敬語に すると？": "「言う」の 尊敬語は「おっしゃる」。謙譲語は「申す」。", "全国どこでも 通じる ことばを 何と いう？": "共通語は 全国どこでも 通じる ことば。場面で 方言と 使い分ける。", "「白い 花が 庭に さいた。」で「白い」は どの ことばを くわしく している？": "「白い」は どんな「花」かを くわしく する。", "「文の ねじれ」とは？": "文の ねじれは 主語と 述語が 合っていない こと。主語と 述語だけを つないで 読むと 見つかる。", "「ゆっくり 歩く。」で「ゆっくり」は どの ことばを くわしく している？": "「ゆっくり」は どのように「歩く」かを くわしく する。", "「わたしが 先生の 家に 行く。」を 謙譲語に すると？": "「行く」の 謙譲語は「うかがう」。尊敬語なら「いらっしゃる」。", "「わたしが 言う。」を 謙譲語に すると？": "「言う」の 謙譲語は「申す」。", "「先生が 来る。」を 尊敬語に すると？": "「来る」の 尊敬語は「いらっしゃる」（おいでに なる）。", "「です」「ます」を つけて ていねいに 言う 敬語は？": "「です・ます」で ていねいに 言うのが 丁寧語。だれに 対しても 使える。", "「先生が 見る。」を 尊敬語に すると？": "「見る」の 尊敬語は「ご覧に なる」。", "「お客様が 食べる。」を 尊敬語に すると？": "「食べる」の 尊敬語は「めしあがる」。"});
  /* j6-hyogen */ (function (a) { for (var k in a) E[k] = a[k]; })({"「わたしは 走った。どこまでも、どこまでも。」で 使われている 工夫は？": "同じ ことばを くり返す 反復。思いの 強さや 長さが 伝わる。", "「君は ぼくの 太陽だ」の 表現の 工夫は？": "「〜のようだ」を 使わず「〜だ」と 言い切る たとえが 隠喩（暗喩）。", "「太陽が わらっている」は どの 表現？": "人で ない ものを 人の ように 表すのが 擬人法。太陽は わらわないが、明るさが 伝わる。", "「夕焼けに そまる 赤い 空。」の ように 名詞で 文を 終える 工夫は？": "名詞（体言）で 文を 終えるのが 体言止め。余韻が 残る。", "「まるで 宝石みたいな 星」は どの 表現？": "「まるで〜みたいな」と はっきり たとえるのが 直喩。", "「行こう、みんなで。」の ように ことばの 順番を 入れかえる 工夫は？": "ふつうの 順番（みんなで 行こう）を 入れかえて 強調するのが 倒置。", "「にこにこ」「きらきら」の ように 様子を 表す ことばを 何と いう？": "様子を 表す ことばが 擬態語（にこにこ・きらきら）。音では ない。", "「星が まばたきを している」は どの 表現？": "星を 人の ように「まばたき」させているので 擬人法。", "「ザーザー」「ゴロゴロ」の ように 音を 表す ことばを 何と いう？": "実際の 音を 表す ことばが 擬音語（ザーザー）。", "「いちめんの なのはな、いちめんの なのはな」の ような 表現の 工夫は？": "同じ ことばを くり返す 反復。山村暮鳥の 詩。一面に 広がる 菜の花が 目に うかぶ。", "「心が 石に なった」は どの 表現？": "「〜のような」を 使わず 心を 石に たとえた 隠喩。かたく 動かない 気持ち。", "「雪のように 白い はだ」の 表現の 工夫は？": "「〜のように」で たとえるので 直喩。", "随筆とは どんな 文章？": "随筆は 筆者の 経験や 感じた こと・考えた ことを 自由に 書いた 文章（例：枕草子）。", "直喩の 目じるしに なる ことばは？": "直喩は「〜のような・〜みたいな・まるで」が 目じるし。ない ときは 隠喩。", "「ドアが バタンと しまった」の「バタン」は？": "ドアの 音を 表すので 擬音語。", "くり返しの 表現が 読み手に あたえる 効果は？": "くり返すと その ことばが 強く 心に 残る。作者が 一番 伝えたい ことが わかる。", "「風が ささやく」の 表現の 工夫は？": "風を 人の ように「ささやく」と 表した 擬人法。", "体言止めの 効果として よいものは？": "体言止めは 文を 言い切らない ので 余韻が 残り、印象が 強く なる。"});
  /* j6-dokkai */ (function (a) { for (var k in a) E[k] = a[k]; })({"【文】Aさんは「給食は 残さず 食べるべきだ」と 言う。Bさんは「量を 自分で えらべると よい」と 言う。\n\n2人の 意見で 共通している ことは？": "Aさんは「残さず 食べる」、Bさんは「量を えらぶ」。方法は ちがうが、どちらも 食べ物を むだに したくない 思い。ちがいの 奥の 共通点を さがそう。", "【文】読書には よい ことが 多い。たとえば、知らない 世界を 知る ことが できる。また、ことばを たくさん 覚えられる。\n\nこの 文章の 要旨は？": "最初の 文が まとめ、「たとえば」「また」は 例。要旨は 例ではなく まとめの 文に ある。", "事実と 意見の ちがいとして 正しいのは？": "事実は 調べて たしかめられる こと、意見は その人の 考え。「〜べきだ」「〜と 思う」は 意見の 目じるし。", "【文】プラスチックの ごみは 海に 流れ、生き物の 命を うばう ことが ある。だから、わたしたちは マイバッグを 使うべきだ。\n\n「だから」の 前と 後ろの 関係は？": "「だから」の 前は 理由（海の 生き物の 命を うばう）、後ろは 主張（マイバッグを 使うべき）。", "【文】ゆいは 朝から 口を きかなかった。けれど、友だちの 手紙を 読むと、ふっと 顔を 上げて 窓を 開けた。\n\nゆいの 気持ちが 変わった きっかけは？": "「けれど」の 後で 様子が 変わる。きっかけは その 直前の「手紙を 読んだ こと」。", "【文】朝、空は どんよりと くもっていた。さきは ため息を ついて、くつひもを むすび直した。\n\n「どんよりと くもった 空」が 表している さきの 気持ちは？": "情景（くもった 空）は 人物の 気持ちを 表す ことが ある。ため息とも 合わせて しずんだ 気持ち。", "【文】夕立が 去った。校庭の 水たまりに、まっさおな 空が うつっている。けんたは ボールを かかえて かけだした。\n\nけんたの 気持ちとして よいのは？": "まっさおな 空・かけだす 動作から、明るく わくわくした 気持ちが 読み取れる。", "【文】はじめ、ぼくは その 犬が こわかった。何度も 会う うちに、しっぽを ふって 近づいて くる 犬を 待つように なった。\n\n「ぼく」の 気持ちの 変化は？": "はじめ「こわかった」→ 何度も 会う うちに「待つように なった」。最初と 最後の 気持ちを くらべる。", "【文】駅前の 自転車置き場は いつも いっぱいだ。わたしは、もっと 広くするべきだと 考える。\n\n意見を 述べている 文は？": "「〜べきだと 考える」は 筆者の 考え（意見）。「いつも いっぱいだ」は 事実。", "【文】ゆいは 朝から 口を きかなかった。けれど、友だちの 手紙を 読むと、ふっと 顔を 上げて 窓を 開けた。\n\n「窓を 開けた」から 想像できる ゆいの 気持ちは？": "口を きかなかった ゆいが 窓を 開けた。行動から 心が 少し 開いた・晴れた ことが 想像できる。", "【文】祖父の 畑では、毎年 トマトが 赤く 実る。今年は 雨が 少なく、実は 小さかった。それでも 祖父は「味は いちばんだ」と 笑った。\n\n祖父の 人柄として 合うのは？": "実が 小さくても「味は いちばんだ」と 笑う。前向きで おおらかな 人柄が わかる。", "説明文の「序論・本論・結論」で、筆者の 考えが まとめて 書かれる ことが 多いのは？": "説明文の 結論で 筆者の 考えが まとめられる ことが 多い。序論（問い）→ 本論（説明）→ 結論（まとめ）。", "物語で、登場人物の 気持ちが 大きく 変わる 場面を 何と いう？": "気持ちが 大きく 変わる 場面は 山場（クライマックス）。物語の 一番 大事な ところ。", "【文】日本の 家には 昔から 縁側が ある。縁側は 外と 内を つなぐ 場所だ。わたしは、人と 人を つなぐ 場所でも あると 思う。\n\n筆者の 考えが いちばん よく 表れている 文は？": "「わたしは〜と 思う」が 筆者の 考え。前の 2文は 説明（事実）。"});
  /* j6-kanji */ (function (a) { for (var k in a) E[k] = a[k]; })({"「蒸気」の読みは？": "「蒸気（じょうき）」＝水などが 熱で 気体に なった もの。「蒸」は くさかんむり＋烝、むす。", "「じょうき」を漢字で書くと？": "「蒸気（じょうき）」＝水などが 熱で 気体に なった もの。「蒸」は くさかんむり＋烝、むす。", "「貴重」の読みは？": "「貴重（きちょう）」＝とても 大切で 価値が ある こと。「貴」は とうとい、下に 貝（お金）。", "「ちいき」と読む漢字はどれ？": "「地域（ちいき）」＝ある 区切られた 土地。「域」は つちへん、土地の 区切り。", "「ぞうき」と読む漢字はどれ？": "「臓器（ぞうき）」＝心臓・肺など 体の 中の はたらく 器官。「臓」は にくづき。", "「しょめい」を漢字で書くと？": "「署名（しょめい）」＝自分の 名前を 書く こと。「署」は あみがしら＋者。", "「灰色」の読みは？": "「灰色（はいいろ）」＝白と 黒の 間の 色。灰（はい）の 色。", "「せいじつ」と読む漢字はどれ？": "「誠実（せいじつ）」＝まごころが あり まじめな こと。「誠」は ごんべん＋成、言った ことを 成しとげる。", "「ずのう」を漢字で書くと？": "「頭脳（ずのう）」＝頭の はたらき・考える 力。「脳」は にくづき。「頭」を「ず」と 読む ことに 注意。", "「頭脳」の読みは？": "「頭脳（ずのう）」＝頭の はたらき・考える 力。「脳」は にくづき。「頭」を「ず」と 読む ことに 注意。", "「順序」の読みは？": "「順序（じゅんじょ）」＝ものごとの 順番。「序」は まだれ、はじめ・順番。", "「けいさつ」を漢字で書くと？": "「警察（けいさつ）」＝人々の 安全を 守る 役所。「警」は いましめる、「察」は よく 見る。", "「ひはん」を漢字で書くと？": "「批判（ひはん）」＝よしあしを 考えて 意見を 言う こと。「批」は てへん、「判」は わける・決める。", "「たんじょう」を漢字で書くと？": "「誕生（たんじょう）」＝生まれる こと。「誕」は ごんべん＋延。", "「げきじょう」を漢字で書くと？": "「劇場（げきじょう）」＝劇を 見る 建物。「劇」の 右は りっとう（刀）。", "「げんじゅう」と読む漢字はどれ？": "「厳重（げんじゅう）」＝とても きびしい こと。「厳」は きびしい・おごそか。", "「とうろん」を漢字で書くと？": "「討論（とうろん）」＝意見を 出し合って 話し合う こと。どちらも ごんべん（言葉）。", "「けんぽう」と読む漢字はどれ？": "「憲法（けんぽう）」＝国の 一番 大切な きまり。「憲」は おきて。", "「体操」の読みは？": "「体操（たいそう）」＝体を 動かして きたえる 運動。「操」は あやつる。てへん（手）で 体を あやつると 覚えよう。", "「しゅうのう」と読む漢字はどれ？": "「収納（しゅうのう）」＝物を しまう こと。「収」も「納」も おさめる 意味の にた 漢字の 組み合わせ。", "「ちいき」を漢字で書くと？": "「地域（ちいき）」＝ある 区切られた 土地。「域」は つちへん、土地の 区切り。", "「せんでん」を漢字で書くと？": "「宣伝（せんでん）」＝多くの 人に 知らせ 広める こと。「宣」は のべる、「伝」は つたえる。", "「ちゅうじつ」と読む漢字はどれ？": "「忠実（ちゅうじつ）」＝まじめに 正しく 守る こと。「忠」は 中＋心、まん中の 心＝まごころ。", "「ふくそう」と読む漢字はどれ？": "「服装（ふくそう）」＝身に つけた 服の ようす。「装」は よそおう、下に 衣。", "「郵便」の読みは？": "「郵便（ゆうびん）」＝手紙や 荷物を とどける しくみ。「郵」は おおざと（村や 町）。", "「かくめい」と読む漢字はどれ？": "「革命（かくめい）」＝しくみを 根本から 大きく 変える こと。「革」は あらためる。", "「してん」を漢字で書くと？": "「視点（してん）」＝物を 見る 立場や 見方。「視」は 見る。", "「おんだん」と読む漢字はどれ？": "「温暖（おんだん）」＝気候が あたたかい こと。「暖」は 日へん、日ざしで あたたかい。", "「存在」の読みは？": "「存在（そんざい）」＝そこに ある・いる こと。「存」も「在」も ある 意味の にた 漢字。", "「宇宙」の読みは？": "「宇宙（うちゅう）」＝地球の 外の 果てしない 空間。どちらも うかんむり（屋根）。大きな 屋根の 下と 覚えよう。", "「そんざい」と読む漢字はどれ？": "「存在（そんざい）」＝そこに ある・いる こと。「存」も「在」も ある 意味の にた 漢字。", "「はいゆう」と読む漢字はどれ？": "「俳優（はいゆう）」＝劇や 映画で 演じる 人。どちらも にんべん（人）。「優」は すぐれる。", "「ひはん」と読む漢字はどれ？": "「批判（ひはん）」＝よしあしを 考えて 意見を 言う こと。「批」は てへん、「判」は わける・決める。", "「しんぞう」と読む漢字はどれ？": "「心臓（しんぞう）」＝血液を 送る 体の 中の ポンプ。「臓」は にくづき（体）＋蔵（しまう）。", "「心臓」の読みは？": "「心臓（しんぞう）」＝血液を 送る 体の 中の ポンプ。「臓」は にくづき（体）＋蔵（しまう）。", "「かくめい」を漢字で書くと？": "「革命（かくめい）」＝しくみを 根本から 大きく 変える こと。「革」は あらためる。", "「じゅもく」と読む漢字はどれ？": "「樹木（じゅもく）」＝立ち木。「樹」も「木」も き。にた 意味の 組み合わせ。", "「樹木」の読みは？": "「樹木（じゅもく）」＝立ち木。「樹」も「木」も き。にた 意味の 組み合わせ。", "「視点」の読みは？": "「視点（してん）」＝物を 見る 立場や 見方。「視」は 見る。", "「署名」の読みは？": "「署名（しょめい）」＝自分の 名前を 書く こと。「署」は あみがしら＋者。", "「温暖」の読みは？": "「温暖（おんだん）」＝気候が あたたかい こと。「暖」は 日へん、日ざしで あたたかい。", "「ひてい」と読む漢字はどれ？": "「否定（ひてい）」＝そうでは ないと 打ち消す こと。「否」は 不＋口、口で「ちがう」と 言う。反対は 肯定。", "「はいいろ」と読む漢字はどれ？": "「灰色（はいいろ）」＝白と 黒の 間の 色。灰（はい）の 色。", "「じしゃく」と読む漢字はどれ？": "「磁石（じしゃく）」＝鉄を 引きつける 石。「磁」は いしへん。", "「きんむ」と読む漢字はどれ？": "「勤務（きんむ）」＝会社などで はたらく こと。「勤」「務」どちらも 力が 入っている。力を 出して はたらく。", "「げきじょう」と読む漢字はどれ？": "「劇場（げきじょう）」＝劇を 見る 建物。「劇」の 右は りっとう（刀）。", "「せんもん」と読む漢字はどれ？": "「専門（せんもん）」＝ある ことだけを 深く 学ぶ・行う こと。「専」に 点は ない ことに 注意。", "「じゅうだん」と読む漢字はどれ？": "「縦断（じゅうだん）」＝たてに 通りぬける こと。「縦」は いとへん、たて。反対は 横断。", "「ちょうじょう」を漢字で書くと？": "「頂上（ちょうじょう）」＝山の 一番 上。「頂」は いただき（頁は 頭）。", "「はいゆう」を漢字で書くと？": "「俳優（はいゆう）」＝劇や 映画で 演じる 人。どちらも にんべん（人）。「優」は すぐれる。", "「疑問」の読みは？": "「疑問（ぎもん）」＝うたがって 問う こと。「疑」は うたがう。", "「ちょきん」と読む漢字はどれ？": "「貯金（ちょきん）」＝お金を ためる こと。「貯」は かいへん（お金）。", "「しげん」を漢字で書くと？": "「資源（しげん）」＝生活や 産業に 役立つ もとに なる もの。「資」は もとで、「源」は みなもと。", "「うちゅう」を漢字で書くと？": "「宇宙（うちゅう）」＝地球の 外の 果てしない 空間。どちらも うかんむり（屋根）。大きな 屋根の 下と 覚えよう。", "「よくじつ」と読む漢字はどれ？": "「翌日（よくじつ）」＝次の 日。「翌」は 羽＋立。", "「ないかく」と読む漢字はどれ？": "「内閣（ないかく）」＝総理大臣と 大臣で つくる 国の 政治の 中心。「閣」は 門がまえ＋各、りっぱな 建物の 意味。", "「ちょきん」を漢字で書くと？": "「貯金（ちょきん）」＝お金を ためる こと。「貯」は かいへん（お金）。", "「預金」の読みは？": "「預金（よきん）」＝銀行に お金を あずける こと。「預」は あずける。貯金（ためる）とのちがい。", "「地域」の読みは？": "「地域（ちいき）」＝ある 区切られた 土地。「域」は つちへん、土地の 区切り。", "「ごかい」を漢字で書くと？": "「誤解（ごかい）」＝まちがって 受け取る こと。「誤」は ごんべん、言葉の あやまり。", "「じゅんじょ」と読む漢字はどれ？": "「順序（じゅんじょ）」＝ものごとの 順番。「序」は まだれ、はじめ・順番。", "「憲法」の読みは？": "「憲法（けんぽう）」＝国の 一番 大切な きまり。「憲」は おきて。", "「たいそう」と読む漢字はどれ？": "「体操（たいそう）」＝体を 動かして きたえる 運動。「操」は あやつる。てへん（手）で 体を あやつると 覚えよう。", "「しょめい」と読む漢字はどれ？": "「署名（しょめい）」＝自分の 名前を 書く こと。「署」は あみがしら＋者。", "「きちょう」と読む漢字はどれ？": "「貴重（きちょう）」＝とても 大切で 価値が ある こと。「貴」は とうとい、下に 貝（お金）。", "「尊敬」の読みは？": "「尊敬（そんけい）」＝すぐれた 人を うやまう こと。「尊」も「敬」も とうとぶ 意味の にた 漢字。", "「危険」の読みは？": "「危険（きけん）」＝あぶない こと。「険」は こざとへん（山や 坂）、けわしい 意味。", "「しょうらい」と読む漢字はどれ？": "「将来（しょうらい）」＝これから 先。「将」は これから〜しようとする。", "「そんけい」を漢字で書くと？": "「尊敬（そんけい）」＝すぐれた 人を うやまう こと。「尊」も「敬」も とうとぶ 意味の にた 漢字。", "「拡大」の読みは？": "「拡大（かくだい）」＝広げて 大きく する こと。「拡」は てへん、手で 広げる。反対は 縮小。", "「ゆうびん」と読む漢字はどれ？": "「郵便（ゆうびん）」＝手紙や 荷物を とどける しくみ。「郵」は おおざと（村や 町）。", "「ないかく」を漢字で書くと？": "「内閣（ないかく）」＝総理大臣と 大臣で つくる 国の 政治の 中心。「閣」は 門がまえ＋各、りっぱな 建物の 意味。", "「うちゅう」と読む漢字はどれ？": "「宇宙（うちゅう）」＝地球の 外の 果てしない 空間。どちらも うかんむり（屋根）。大きな 屋根の 下と 覚えよう。", "「朗読」の読みは？": "「朗読（ろうどく）」＝声に 出して 読む こと。「朗」は ほがらか、明るく 声を 出す。", "「そんけい」と読む漢字はどれ？": "「尊敬（そんけい）」＝すぐれた 人を うやまう こと。「尊」も「敬」も とうとぶ 意味の にた 漢字。", "「はいいろ」を漢字で書くと？": "「灰色（はいいろ）」＝白と 黒の 間の 色。灰（はい）の 色。", "「すんぽう」を漢字で書くと？": "「寸法（すんぽう）」＝物の 長さや 大きさ。「寸」は 昔の 長さの 単位。", "「至急」の読みは？": "「至急（しきゅう）」＝とても 急ぐ こと。「至」は いたる、きわまる。", "「縦断」の読みは？": "「縦断（じゅうだん）」＝たてに 通りぬける こと。「縦」は いとへん、たて。反対は 横断。", "「否定」の読みは？": "「否定（ひてい）」＝そうでは ないと 打ち消す こと。「否」は 不＋口、口で「ちがう」と 言う。反対は 肯定。", "「しょうらい」を漢字で書くと？": "「将来（しょうらい）」＝これから 先。「将」は これから〜しようとする。", "「映像」の読みは？": "「映像（えいぞう）」＝画面に うつる すがた。「映」は 日（光）で うつす、「像」は にんべん、すがた。", "「りんじ」を漢字で書くと？": "「臨時（りんじ）」＝その ときだけ 特別に。「臨」は のぞむ（その 場に 出る）。", "「ちょうじょう」と読む漢字はどれ？": "「頂上（ちょうじょう）」＝山の 一番 上。「頂」は いただき（頁は 頭）。", "「じょうき」と読む漢字はどれ？": "「蒸気（じょうき）」＝水などが 熱で 気体に なった もの。「蒸」は くさかんむり＋烝、むす。", "「しきゅう」と読む漢字はどれ？": "「至急（しきゅう）」＝とても 急ぐ こと。「至」は いたる、きわまる。", "「かんたん」を漢字で書くと？": "「簡単（かんたん）」＝やさしく 手軽な こと。「簡」は たけかんむり（竹）。昔の 竹の ふだ から。", "「討論」の読みは？": "「討論（とうろん）」＝意見を 出し合って 話し合う こと。どちらも ごんべん（言葉）。", "「専門」の読みは？": "「専門（せんもん）」＝ある ことだけを 深く 学ぶ・行う こと。「専」に 点は ない ことに 注意。", "「たいそう」を漢字で書くと？": "「体操（たいそう）」＝体を 動かして きたえる 運動。「操」は あやつる。てへん（手）で 体を あやつると 覚えよう。", "「けいざい」と読む漢字はどれ？": "「経済（けいざい）」＝お金や 物の 動き。「経世済民（世を おさめ 民を 救う）」の 略。", "「ずのう」と読む漢字はどれ？": "「頭脳（ずのう）」＝頭の はたらき・考える 力。「脳」は にくづき。「頭」を「ず」と 読む ことに 注意。", "「そんざい」を漢字で書くと？": "「存在（そんざい）」＝そこに ある・いる こと。「存」も「在」も ある 意味の にた 漢字。", "「おんだん」を漢字で書くと？": "「温暖（おんだん）」＝気候が あたたかい こと。「暖」は 日へん、日ざしで あたたかい。", "「しげん」と読む漢字はどれ？": "「資源（しげん）」＝生活や 産業に 役立つ もとに なる もの。「資」は もとで、「源」は みなもと。", "「ぎもん」を漢字で書くと？": "「疑問（ぎもん）」＝うたがって 問う こと。「疑」は うたがう。", "「収納」の読みは？": "「収納（しゅうのう）」＝物を しまう こと。「収」も「納」も おさめる 意味の にた 漢字の 組み合わせ。", "「ろうどく」と読む漢字はどれ？": "「朗読（ろうどく）」＝声に 出して 読む こと。「朗」は ほがらか、明るく 声を 出す。", "「げんじゅう」を漢字で書くと？": "「厳重（げんじゅう）」＝とても きびしい こと。「厳」は きびしい・おごそか。", "「警察」の読みは？": "「警察（けいさつ）」＝人々の 安全を 守る 役所。「警」は いましめる、「察」は よく 見る。", "「磁石」の読みは？": "「磁石（じしゃく）」＝鉄を 引きつける 石。「磁」は いしへん。", "「ぎもん」と読む漢字はどれ？": "「疑問（ぎもん）」＝うたがって 問う こと。「疑」は うたがう。", "「たんじょう」と読む漢字はどれ？": "「誕生（たんじょう）」＝生まれる こと。「誕」は ごんべん＋延。", "「ぞうき」を漢字で書くと？": "「臓器（ぞうき）」＝心臓・肺など 体の 中の はたらく 器官。「臓」は にくづき。", "「簡単」の読みは？": "「簡単（かんたん）」＝やさしく 手軽な こと。「簡」は たけかんむり（竹）。昔の 竹の ふだ から。", "「えいぞう」と読む漢字はどれ？": "「映像（えいぞう）」＝画面に うつる すがた。「映」は 日（光）で うつす、「像」は にんべん、すがた。", "「きけん」を漢字で書くと？": "「危険（きけん）」＝あぶない こと。「険」は こざとへん（山や 坂）、けわしい 意味。", "「せいじつ」を漢字で書くと？": "「誠実（せいじつ）」＝まごころが あり まじめな こと。「誠」は ごんべん＋成、言った ことを 成しとげる。", "「じゅんじょ」を漢字で書くと？": "「順序（じゅんじょ）」＝ものごとの 順番。「序」は まだれ、はじめ・順番。", "「俳優」の読みは？": "「俳優（はいゆう）」＝劇や 映画で 演じる 人。どちらも にんべん（人）。「優」は すぐれる。", "「批判」の読みは？": "「批判（ひはん）」＝よしあしを 考えて 意見を 言う こと。「批」は てへん、「判」は わける・決める。", "「秘密」の読みは？": "「秘密（ひみつ）」＝人に かくして 知らせない こと。「秘」は のぎへん、「密」は うかんむり＋必＋山。", "「資源」の読みは？": "「資源（しげん）」＝生活や 産業に 役立つ もとに なる もの。「資」は もとで、「源」は みなもと。", "「しゅくしゃく」を漢字で書くと？": "「縮尺（しゅくしゃく）」＝地図で 実際の きょりを ちぢめた 割合。「縮」は ちぢむ、「尺」は 長さ。", "「りんじ」と読む漢字はどれ？": "「臨時（りんじ）」＝その ときだけ 特別に。「臨」は のぞむ（その 場に 出る）。", "「しきゅう」を漢字で書くと？": "「至急（しきゅう）」＝とても 急ぐ こと。「至」は いたる、きわまる。", "「かくだい」と読む漢字はどれ？": "「拡大（かくだい）」＝広げて 大きく する こと。「拡」は てへん、手で 広げる。反対は 縮小。", "「宣伝」の読みは？": "「宣伝（せんでん）」＝多くの 人に 知らせ 広める こと。「宣」は のべる、「伝」は つたえる。", "「将来」の読みは？": "「将来（しょうらい）」＝これから 先。「将」は これから〜しようとする。", "「経済」の読みは？": "「経済（けいざい）」＝お金や 物の 動き。「経世済民（世を おさめ 民を 救う）」の 略。", "「ちゅうじつ」を漢字で書くと？": "「忠実（ちゅうじつ）」＝まじめに 正しく 守る こと。「忠」は 中＋心、まん中の 心＝まごころ。", "「よくじつ」を漢字で書くと？": "「翌日（よくじつ）」＝次の 日。「翌」は 羽＋立。", "「ろうどく」を漢字で書くと？": "「朗読（ろうどく）」＝声に 出して 読む こと。「朗」は ほがらか、明るく 声を 出す。", "「しゅうのう」を漢字で書くと？": "「収納（しゅうのう）」＝物を しまう こと。「収」も「納」も おさめる 意味の にた 漢字の 組み合わせ。", "「翌日」の読みは？": "「翌日（よくじつ）」＝次の 日。「翌」は 羽＋立。", "「ひみつ」と読む漢字はどれ？": "「秘密（ひみつ）」＝人に かくして 知らせない こと。「秘」は のぎへん、「密」は うかんむり＋必＋山。", "「誕生」の読みは？": "「誕生（たんじょう）」＝生まれる こと。「誕」は ごんべん＋延。", "「頂上」の読みは？": "「頂上（ちょうじょう）」＝山の 一番 上。「頂」は いただき（頁は 頭）。", "「じゅうだん」を漢字で書くと？": "「縦断（じゅうだん）」＝たてに 通りぬける こと。「縦」は いとへん、たて。反対は 横断。", "「ひみつ」を漢字で書くと？": "「秘密（ひみつ）」＝人に かくして 知らせない こと。「秘」は のぎへん、「密」は うかんむり＋必＋山。", "「厳重」の読みは？": "「厳重（げんじゅう）」＝とても きびしい こと。「厳」は きびしい・おごそか。", "「してん」と読む漢字はどれ？": "「視点（してん）」＝物を 見る 立場や 見方。「視」は 見る。", "「誠実」の読みは？": "「誠実（せいじつ）」＝まごころが あり まじめな こと。「誠」は ごんべん＋成、言った ことを 成しとげる。", "「きちょう」を漢字で書くと？": "「貴重（きちょう）」＝とても 大切で 価値が ある こと。「貴」は とうとい、下に 貝（お金）。", "「ゆうびん」を漢字で書くと？": "「郵便（ゆうびん）」＝手紙や 荷物を とどける しくみ。「郵」は おおざと（村や 町）。", "「劇場」の読みは？": "「劇場（げきじょう）」＝劇を 見る 建物。「劇」の 右は りっとう（刀）。", "「ひてい」を漢字で書くと？": "「否定（ひてい）」＝そうでは ないと 打ち消す こと。「否」は 不＋口、口で「ちがう」と 言う。反対は 肯定。", "「しんぞう」を漢字で書くと？": "「心臓（しんぞう）」＝血液を 送る 体の 中の ポンプ。「臓」は にくづき（体）＋蔵（しまう）。", "「内閣」の読みは？": "「内閣（ないかく）」＝総理大臣と 大臣で つくる 国の 政治の 中心。「閣」は 門がまえ＋各、りっぱな 建物の 意味。", "「かんたん」と読む漢字はどれ？": "「簡単（かんたん）」＝やさしく 手軽な こと。「簡」は たけかんむり（竹）。昔の 竹の ふだ から。", "「じしゃく」を漢字で書くと？": "「磁石（じしゃく）」＝鉄を 引きつける 石。「磁」は いしへん。", "「忠実」の読みは？": "「忠実（ちゅうじつ）」＝まじめに 正しく 守る こと。「忠」は 中＋心、まん中の 心＝まごころ。", "「勤務」の読みは？": "「勤務（きんむ）」＝会社などで はたらく こと。「勤」「務」どちらも 力が 入っている。力を 出して はたらく。", "「服装」の読みは？": "「服装（ふくそう）」＝身に つけた 服の ようす。「装」は よそおう、下に 衣。", "「けいざい」を漢字で書くと？": "「経済（けいざい）」＝お金や 物の 動き。「経世済民（世を おさめ 民を 救う）」の 略。", "「とうろん」と読む漢字はどれ？": "「討論（とうろん）」＝意見を 出し合って 話し合う こと。どちらも ごんべん（言葉）。", "「誤解」の読みは？": "「誤解（ごかい）」＝まちがって 受け取る こと。「誤」は ごんべん、言葉の あやまり。", "「せんもん」を漢字で書くと？": "「専門（せんもん）」＝ある ことだけを 深く 学ぶ・行う こと。「専」に 点は ない ことに 注意。", "「けんぽう」を漢字で書くと？": "「憲法（けんぽう）」＝国の 一番 大切な きまり。「憲」は おきて。", "「きんむ」を漢字で書くと？": "「勤務（きんむ）」＝会社などで はたらく こと。「勤」「務」どちらも 力が 入っている。力を 出して はたらく。", "「かくだい」を漢字で書くと？": "「拡大（かくだい）」＝広げて 大きく する こと。「拡」は てへん、手で 広げる。反対は 縮小。", "「ふくそう」を漢字で書くと？": "「服装（ふくそう）」＝身に つけた 服の ようす。「装」は よそおう、下に 衣。", "「えいぞう」を漢字で書くと？": "「映像（えいぞう）」＝画面に うつる すがた。「映」は 日（光）で うつす、「像」は にんべん、すがた。", "「臨時」の読みは？": "「臨時（りんじ）」＝その ときだけ 特別に。「臨」は のぞむ（その 場に 出る）。", "「縮尺」の読みは？": "「縮尺（しゅくしゃく）」＝地図で 実際の きょりを ちぢめた 割合。「縮」は ちぢむ、「尺」は 長さ。", "「臓器」の読みは？": "「臓器（ぞうき）」＝心臓・肺など 体の 中の はたらく 器官。「臓」は にくづき。", "「よきん」と読む漢字はどれ？": "「預金（よきん）」＝銀行に お金を あずける こと。「預」は あずける。貯金（ためる）とのちがい。", "「じゅもく」を漢字で書くと？": "「樹木（じゅもく）」＝立ち木。「樹」も「木」も き。にた 意味の 組み合わせ。", "「よきん」を漢字で書くと？": "「預金（よきん）」＝銀行に お金を あずける こと。「預」は あずける。貯金（ためる）とのちがい。", "「ごかい」と読む漢字はどれ？": "「誤解（ごかい）」＝まちがって 受け取る こと。「誤」は ごんべん、言葉の あやまり。", "「貯金」の読みは？": "「貯金（ちょきん）」＝お金を ためる こと。「貯」は かいへん（お金）。", "「けいさつ」と読む漢字はどれ？": "「警察（けいさつ）」＝人々の 安全を 守る 役所。「警」は いましめる、「察」は よく 見る。", "「きけん」と読む漢字はどれ？": "「危険（きけん）」＝あぶない こと。「険」は こざとへん（山や 坂）、けわしい 意味。", "「すんぽう」と読む漢字はどれ？": "「寸法（すんぽう）」＝物の 長さや 大きさ。「寸」は 昔の 長さの 単位。", "「寸法」の読みは？": "「寸法（すんぽう）」＝物の 長さや 大きさ。「寸」は 昔の 長さの 単位。", "「せんでん」と読む漢字はどれ？": "「宣伝（せんでん）」＝多くの 人に 知らせ 広める こと。「宣」は のべる、「伝」は つたえる。", "「革命」の読みは？": "「革命（かくめい）」＝しくみを 根本から 大きく 変える こと。「革」は あらためる。", "「しゅくしゃく」と読む漢字はどれ？": "「縮尺（しゅくしゃく）」＝地図で 実際の きょりを ちぢめた 割合。「縮」は ちぢむ、「尺」は 長さ。"});
  /* j6-kaki */ (function (a) { for (var k in a) E[k] = a[k]; })({"「地図の シュクシャク」\nカタカナ「シュクシャク」を 漢字で 書くと？": "「縮尺（しゅくしゃく）」＝地図で 実際の きょりを ちぢめた 割合。「縮」は ちぢむ、「尺」は 長さ。", "「カンケツに 話す」\nカタカナ「カンケツ」を 漢字で 書くと？": "「簡潔（かんけつ）」＝むだが なく 短い こと。「潔」は いさぎよい・さっぱり。", "「カクメイが おこる」\nカタカナ「カクメイ」を 漢字で 書くと？": "「革命（かくめい）」＝しくみを 根本から 大きく 変える こと。「革」は あらためる。", "「フクソウを ととのえる」\nカタカナ「フクソウ」を 漢字で 書くと？": "「服装（ふくそう）」＝身に つけた 服の ようす。「装」は よそおう、下に 衣。", "「朝の タイソウ」\nカタカナ「タイソウ」を 漢字で 書くと？": "「体操（たいそう）」＝体を 動かして きたえる 運動。「操」は あやつる。てへん（手）で 体を あやつると 覚えよう。", "「ケンポウを 守る」\nカタカナ「ケンポウ」を 漢字で 書くと？": "「憲法（けんぽう）」＝国の 一番 大切な きまり。「憲」は おきて。", "「シュウノウ 場所」\nカタカナ「シュウノウ」を 漢字で 書くと？": "「収納（しゅうのう）」＝物を しまう こと。「収」も「納」も おさめる 意味の にた 漢字の 組み合わせ。", "「銀行の ヨキン」\nカタカナ「ヨキン」を 漢字で 書くと？": "「預金（よきん）」＝銀行に お金を あずける こと。「預」は あずける。貯金（ためる）とのちがい。", "「シャソウから 見る 景色」\nカタカナ「シャソウ」を 漢字で 書くと？": "「車窓（しゃそう）」＝車や 電車の まど。「窓」は あなかんむり。", "「ユウビン局」\nカタカナ「ユウビン」を 漢字で 書くと？": "「郵便（ゆうびん）」＝手紙や 荷物を とどける しくみ。「郵」は おおざと（村や 町）。", "「スンポウを はかる」\nカタカナ「スンポウ」を 漢字で 書くと？": "「寸法（すんぽう）」＝物の 長さや 大きさ。「寸」は 昔の 長さの 単位。", "「チイキの 行事」\nカタカナ「チイキ」を 漢字で 書くと？": "「地域（ちいき）」＝ある 区切られた 土地。「域」は つちへん、土地の 区切り。", "「国の ケイザイ」\nカタカナ「ケイザイ」を 漢字で 書くと？": "「経済（けいざい）」＝お金や 物の 動き。「経世済民（世を おさめ 民を 救う）」の 略。", "「体の ゾウキ」\nカタカナ「ゾウキ」を 漢字で 書くと？": "「臓器（ぞうき）」＝心臓・肺など 体の 中の はたらく 器官。「臓」は にくづき。", "「シキュウ 連らくを」\nカタカナ「シキュウ」を 漢字で 書くと？": "「至急（しきゅう）」＝とても 急ぐ こと。「至」は いたる、きわまる。", "「リンジ 休校」\nカタカナ「リンジ」を 漢字で 書くと？": "「臨時（りんじ）」＝その ときだけ 特別に。「臨」は のぞむ（その 場に 出る）。", "「ギモンに 思う」\nカタカナ「ギモン」を 漢字で 書くと？": "「疑問（ぎもん）」＝うたがって 問う こと。「疑」は うたがう。", "「クラスで トウロンする」\nカタカナ「クラス」を 漢字で 書くと？": "「討論（とうろん）」＝意見を 出し合って 話し合う こと。どちらも ごんべん（言葉）。", "「ショメイを 集める」\nカタカナ「ショメイ」を 漢字で 書くと？": "「署名（しょめい）」＝自分の 名前を 書く こと。「署」は あみがしら＋者。", "「ジュモクを 植える」\nカタカナ「ジュモク」を 漢字で 書くと？": "「樹木（じゅもく）」＝立ち木。「樹」も「木」も き。にた 意味の 組み合わせ。", "「ゲンジュウに しまう」\nカタカナ「ゲンジュウ」を 漢字で 書くと？": "「厳重（げんじゅう）」＝とても きびしい こと。「厳」は きびしい・おごそか。", "「エイゾウを 見る」\nカタカナ「エイゾウ」を 漢字で 書くと？": "「映像（えいぞう）」＝画面に うつる すがた。「映」は 日（光）で うつす、「像」は にんべん、すがた。", "「会社に キンムする」\nカタカナ「キンム」を 漢字で 書くと？": "「勤務（きんむ）」＝会社などで はたらく こと。「勤」「務」どちらも 力が 入っている。力を 出して はたらく。", "「日本を ジュウダンする 旅」\nカタカナ「ジュウダン」を 漢字で 書くと？": "「縦断（じゅうだん）」＝たてに 通りぬける こと。「縦」は いとへん、たて。反対は 横断。", "「ハイユウに なりたい」\nカタカナ「ハイユウ」を 漢字で 書くと？": "「俳優（はいゆう）」＝劇や 映画で 演じる 人。どちらも にんべん（人）。「優」は すぐれる。", "「ゴカイを とく」\nカタカナ「ゴカイ」を 漢字で 書くと？": "「誤解（ごかい）」＝まちがって 受け取る こと。「誤」は ごんべん、言葉の あやまり。", "「センモン家に 聞く」\nカタカナ「センモン」を 漢字で 書くと？": "「専門（せんもん）」＝ある ことだけを 深く 学ぶ・行う こと。「専」に 点は ない ことに 注意。", "「ウチュウ飛行士」\nカタカナ「ウチュウ」を 漢字で 書くと？": "「宇宙（うちゅう）」＝地球の 外の 果てしない 空間。どちらも うかんむり（屋根）。大きな 屋根の 下と 覚えよう。", "「詩の ロウドク」\nカタカナ「ロウドク」を 漢字で 書くと？": "「朗読（ろうどく）」＝声に 出して 読む こと。「朗」は ほがらか、明るく 声を 出す。", "「ソンケイする 人」\nカタカナ「ソンケイ」を 漢字で 書くと？": "「尊敬（そんけい）」＝すぐれた 人を うやまう こと。「尊」も「敬」も とうとぶ 意味の にた 漢字。", "「カンタンな 問題」\nカタカナ「カンタン」を 漢字で 書くと？": "「簡単（かんたん）」＝やさしく 手軽な こと。「簡」は たけかんむり（竹）。昔の 竹の ふだ から。", "「ケイサツ官」\nカタカナ「ケイサツ」を 漢字で 書くと？": "「警察（けいさつ）」＝人々の 安全を 守る 役所。「警」は いましめる、「察」は よく 見る。", "「ゲキジョウで 見る」\nカタカナ「ゲキジョウ」を 漢字で 書くと？": "「劇場（げきじょう）」＝劇を 見る 建物。「劇」の 右は りっとう（刀）。", "「ショウボウ車が 走る」\nカタカナ「ショウボウ」を 漢字で 書くと？": "「消防（しょうぼう）」＝火事を 消し、防ぐ こと。「防」は こざとへん、ふせぐ。", "「シテンを 変えて 考える」\nカタカナ「シテン」を 漢字で 書くと？": "「視点（してん）」＝物を 見る 立場や 見方。「視」は 見る。", "「ジシャクに つく」\nカタカナ「ジシャク」を 漢字で 書くと？": "「磁石（じしゃく）」＝鉄を 引きつける 石。「磁」は いしへん。", "「ナイカクの 会議」\nカタカナ「ナイカク」を 漢字で 書くと？": "「内閣（ないかく）」＝総理大臣と 大臣で つくる 国の 政治の 中心。「閣」は 門がまえ＋各、りっぱな 建物の 意味。", "「毎月 チョキンを する」\nカタカナ「チョキン」を 漢字で 書くと？": "「貯金（ちょきん）」＝お金を ためる こと。「貯」は かいへん（お金）。", "「キチョウな 体験」\nカタカナ「キチョウ」を 漢字で 書くと？": "「貴重（きちょう）」＝とても 大切で 価値が ある こと。「貴」は とうとい、下に 貝（お金）。", "「新商品の センデン」\nカタカナ「センデン」を 漢字で 書くと？": "「宣伝（せんでん）」＝多くの 人に 知らせ 広める こと。「宣」は のべる、「伝」は つたえる。", "「うわさを ヒテイする」\nカタカナ「ヒテイ」を 漢字で 書くと？": "「否定（ひてい）」＝そうでは ないと 打ち消す こと。「否」は 不＋口、口で「ちがう」と 言う。反対は 肯定。", "「ヨクジツの 朝」\nカタカナ「ヨクジツ」を 漢字で 書くと？": "「翌日（よくじつ）」＝次の 日。「翌」は 羽＋立。", "「山の チョウジョウ」\nカタカナ「チョウジョウ」を 漢字で 書くと？": "「頂上（ちょうじょう）」＝山の 一番 上。「頂」は いただき（頁は 頭）。", "「写真を カクダイする」\nカタカナ「カクダイ」を 漢字で 書くと？": "「拡大（かくだい）」＝広げて 大きく する こと。「拡」は てへん、手で 広げる。反対は 縮小。", "「ミンシュウの 声」\nカタカナ「ミンシュウ」を 漢字で 書くと？": "「民衆（みんしゅう）」＝世の中の 多くの 人々。「衆」は 多くの 人。", "「チュウジツに 守る」\nカタカナ「チュウジツ」を 漢字で 書くと？": "「忠実（ちゅうじつ）」＝まじめに 正しく 守る こと。「忠」は 中＋心、まん中の 心＝まごころ。", "「ソンザイに 気づく」\nカタカナ「ソンザイ」を 漢字で 書くと？": "「存在（そんざい）」＝そこに ある・いる こと。「存」も「在」も ある 意味の にた 漢字。", "「ショウライの 夢」\nカタカナ「ショウライ」を 漢字で 書くと？": "「将来（しょうらい）」＝これから 先。「将」は これから〜しようとする。", "「ジュンジョよく ならぶ」\nカタカナ「ジュンジョ」を 漢字で 書くと？": "「順序（じゅんじょ）」＝ものごとの 順番。「序」は まだれ、はじめ・順番。", "「シンゾウの 音」\nカタカナ「シンゾウ」を 漢字で 書くと？": "「心臓（しんぞう）」＝血液を 送る 体の 中の ポンプ。「臓」は にくづき（体）＋蔵（しまう）。", "「セイジツな 人」\nカタカナ「セイジツ」を 漢字で 書くと？": "「誠実（せいじつ）」＝まごころが あり まじめな こと。「誠」は ごんべん＋成、言った ことを 成しとげる。", "「キケンな 場所」\nカタカナ「キケン」を 漢字で 書くと？": "「危険（きけん）」＝あぶない こと。「険」は こざとへん（山や 坂）、けわしい 意味。", "「意見を ヒハンする」\nカタカナ「ヒハン」を 漢字で 書くと？": "「批判（ひはん）」＝よしあしを 考えて 意見を 言う こと。「批」は てへん、「判」は わける・決める。", "「すぐれた ズノウ」\nカタカナ「ズノウ」を 漢字で 書くと？": "「頭脳（ずのう）」＝頭の はたらき・考える 力。「脳」は にくづき。「頭」を「ず」と 読む ことに 注意。", "「ハイイロの 雲」\nカタカナ「ハイイロ」を 漢字で 書くと？": "「灰色（はいいろ）」＝白と 黒の 間の 色。灰（はい）の 色。", "「オンダンな 気候」\nカタカナ「オンダン」を 漢字で 書くと？": "「温暖（おんだん）」＝気候が あたたかい こと。「暖」は 日へん、日ざしで あたたかい。", "「作品の テンラン会」\nカタカナ「テンラン」を 漢字で 書くと？": "「展覧（てんらん）」＝作品などを ならべて 見せる こと。「覧」は 見る。展覧会。", "「ヒミツを 守る」\nカタカナ「ヒミツ」を 漢字で 書くと？": "「秘密（ひみつ）」＝人に かくして 知らせない こと。「秘」は のぎへん、「密」は うかんむり＋必＋山。", "「ジョウキ機関車」\nカタカナ「ジョウキ」を 漢字で 書くと？": "「蒸気（じょうき）」＝水などが 熱で 気体に なった もの。「蒸」は くさかんむり＋烝、むす。", "「ハイクを 作る」\nカタカナ「ハイク」を 漢字で 書くと？": "「俳句（はいく）」＝五・七・五の 短い 詩。「俳」は にんべん＋非。", "「タンジョウ日の 会」\nカタカナ「タンジョウ」を 漢字で 書くと？": "「誕生（たんじょう）」＝生まれる こと。「誕」は ごんべん＋延。", "「シゲンを 大切に」\nカタカナ「シゲン」を 漢字で 書くと？": "「資源（しげん）」＝生活や 産業に 役立つ もとに なる もの。「資」は もとで、「源」は みなもと。"});
  /* e6-me */ (function (a) { for (var k in a) E[k] = a[k]; })({"「たいてい」を 表す ことばは？": "usually は「たいてい・ふだん」。always（いつも）＞usually（たいてい）＞sometimes（ときどき）＞never（ぜんぜん）の 順で 覚えよう。", "「わたしは 毎日 7時に 朝ごはんを 食べます。」": "I eat breakfast（朝ごはんを 食べる）at 7（7時に）every day（毎日）。時こくは at を 使う。", "「何の スポーツが 好き？」と たずねる 文は？": "What sport（何の スポーツ）do you like?（好きですか）。What の 後ろに ものの 種類を つけると「何の〜」。", "自己紹介の さいごに「何か 質問は ありますか？」と 聞くとき": "Any questions? は「何か 質問は ありますか？」。発表の さいごに よく 使う。", "What time do you usually get up?　に 合う 答えは？": "What time（何時）と 聞かれたら 時こくで 答える。get up＝起きる。", "「それは 祖母から もらいました。」に 近い 言い方は？": "It's from 〜.＝それは 〜から（来た もの）です。人や 国を 入れられる。", "Do you have a cat?　に「いいえ」で 答える": "Do you〜? には Yes, I do. ／ No, I don't. で 答える。", "「ときどき」を 表す ことばは？": "sometimes は「ときどき」。", "「わたしは 6年生です。」": "I'm in the sixth grade.＝6年生です。grade は 学年。sixth は「6番目の」。", "I always wash the dishes. の 意味は？": "always＝いつも、wash the dishes＝皿を 洗う。", "What time do you usually go to bed?　に 合う 答えは？": "go to bed＝ねる。p.m. は 午後。", "「ぜんぜん〜しない」を 表す ことばは？": "never は「ぜんぜん〜しない」。not を 使わなくても 打ち消しに なる。", "「いつも」を 表す ことばは？": "always は「いつも」。100％ の イメージ。", "相手が 家の 手伝いを しないと 言ったら、「いいね！」と 返す ことば": "Lucky you! は「いいなあ！」。相手を うらやましく 思う 気持ちを 伝える。", "英語で 名前を 言う とき": "I'm 〜.＝わたしは 〜です。名前を 言う ときの 基本。", "I'm good at swimming. の 意味は？": "be good at 〜＝〜が 得意。swimming＝水泳。", "「わたしは サッカーが 好きです。」を 英語で 言うと？": "I like 〜.＝〜が 好きです。", "「わたしの 宝物は この ボールです。」": "treasure は「宝物」。My treasure is 〜.＝わたしの 宝物は 〜です。", "「わたしは 犬を 飼っています。」": "have は「持っている」の ほかに「飼っている」の 意味でも 使う。", "I never walk the dog. の 意味は？": "never＝ぜんぜん〜しない。walk the dog＝犬の 散歩を する。"});
  /* e6-past */ (function (a) { for (var k in a) E[k] = a[k]; })({"「それは すばらしかったです。」": "It was 〜.＝それは 〜でした。is の 過去形が was。great＝すばらしい。", "「I（　）to the sea.」→「海に 行きました」は？": "go（行く）の 過去形は went。形が 大きく 変わる ので 注意。", "「I（　）camping.」→「キャンプを 楽しみました」は？": "enjoy（楽しむ）の 過去形は enjoyed。ed を つけると 過去に なる。", "相手の 話に「かっこいい！」と 反応する ことば": "Cool! は「かっこいい！」「すごい！」。相手の 話に 反応すると 会話が 続く。", "I saw many deer in Nara. の 意味は？": "saw は see（見る）の 過去形。deer（シカ）は たくさんでも deer の まま。", "「わたしは 公園に 行きました。」": "went は go の 過去形。to the park＝公園へ。", "「わたしの いちばんの 思い出は 修学旅行です。」": "best memory＝いちばんの 思い出。school trip＝修学旅行。", "「わたしは 野球の 試合を 楽しみました。」": "enjoyed watching 〜＝〜を 見るのを 楽しんだ。", "「I（　）tennis.」→「テニスを しました」は？": "play の 過去形は played。ed を つける。", "「わたしたちは 東大寺に 行きました。」": "We went to 〜.＝わたしたちは 〜に 行きました。", "How was your weekend?　に 合う 答えは？": "How was 〜?＝〜は どうでしたか？ には It was 〜. で 答える。fun＝楽しい。", "What's your best memory?　の 意味は？": "What's your best memory?＝いちばんの 思い出は 何？ 卒業前の 定番の 質問。", "「I（　）a rainbow.」→「にじを 見ました」は？": "see の 過去形は saw。", "「I（　）sushi.」→「すしを 食べました」は？": "eat の 過去形は ate。", "「わたしは カレーライスを 食べました。」": "ate は eat の 過去形。curry and rice＝カレーライス。", "「それは 古くて すばらしかった。」": "It was old and great.＝古くて すばらしかった。and で 2つの 様子を つなぐ。", "運動会を 英語で 言うと？": "sports day＝運動会。sports（スポーツ）＋day（日）。", "How was your weekend? の 意味は？": "How was 〜?＝〜は どうでしたか。weekend＝週末。", "「〜した」と 過去の ことを 言う 文は どれ？": "yesterday（昨日）と played（過去形）で 過去の ことだと わかる。", "会話の さいごに「話せて 楽しかったよ。」": "Nice talking to you.＝話せて 楽しかった。会話の しめくくりの ことば。"});
